.card-stack{--design-px:calc(100vh / 1080);position:absolute;left:50%;transform:translate(-50%, -50%);z-index:10;width:calc(698 * var(--design-px));height:calc(182 * var(--design-px));top:calc(805 * var(--design-px));}
