.sub-edge{position:absolute;width:100%;height:100%;z-index:-1;left:0;top:8px;border-radius:3px;background:repeating-linear-gradient(2deg,#835029 0px,#98643a 1.5px,#c39561 2.3px,#9e6b3d 4.6px,#704421 5.6px);box-shadow:inset 0 -2px 0 #4b2d18,0 2px 0 #472a18,0 5px 7px #170e0980;}
