.woodcut-figure path{stroke:#813e27;stroke-width:5;}
.wood-grain{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:0;}
.woodcut-figure circle{stroke-width:5;}
.wood-work{position:absolute;inset:0;transform-origin:50% 50%;}
